<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { apiFetch } from '@/utils/api';
const loading=ref(true), error=ref(''), config=ref<any>(null), syncing=ref(false), message=ref('');
async function load(){try{config.value=await apiFetch('/admin/integrations/config')}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function sync(){syncing.value=true;message.value='';try{const d=await apiFetch('/admin/integrations/sync',{method:'POST'});message.value=d.message||'Sync accepted'}catch(e:any){error.value=e.message}finally{syncing.value=false}}
onMounted(load)
</script>
<template><v-row><v-col cols="12"><v-card elevation="0" class="border rounded-lg"><v-card-item><v-card-title>Provider Configuration</v-card-title><v-card-subtitle>API credentials stay on the backend. The admin UI only receives provider status and masked key information.</v-card-subtitle></v-card-item><v-card-text><v-alert type="info" variant="tonal" class="mb-5">Configure keys in <b>bratips-backend/.env</b>, not in the Vue <b>.env</b>. Never put provider secrets in variables beginning with <b>VITE_</b>.</v-alert><v-alert v-if="error" type="error" variant="tonal" class="mb-4">{{error}}</v-alert><v-progress-linear v-if="loading" indeterminate/><v-row v-if="config"><v-col v-for="(p,name) in config.providers" :key="name" cols="12" md="4"><v-card variant="tonal"><v-card-item><template #append><v-chip :color="p.configured?'success':'warning'">{{p.configured?'Configured':'Missing key'}}</v-chip></template><v-card-title class="text-capitalize">{{name}}</v-card-title></v-card-item><v-card-text><div><b>Provider:</b> {{p.provider}}</div><div><b>Base URL:</b> {{p.baseUrl}}</div><div><b>API key:</b> {{p.keyLast4||'Not configured'}}</div></v-card-text></v-card></v-col></v-row><div class="mt-5"><v-btn color="primary" :loading="syncing" @click="sync">Run Data Sync</v-btn></div><v-alert v-if="message" type="success" variant="tonal" class="mt-4">{{message}}</v-alert></v-card-text></v-card></v-col></v-row></template>
